package io.github.marmer.matchergenerator.core.spi;

import java.util.Objects;

/**
 * A source file generated by a {@link GeneratorBackend}.
 *
 * @param packageName the package the file belongs to
 * @param simpleName  the simple name of the generated type, which is also the file name without extension
 * @param language    the language of the content
 * @param content     the complete file content
 */
public record GeneratedSource(String packageName, String simpleName, Language language, String content) {

    public GeneratedSource {
        Objects.requireNonNull(packageName, "packageName");
        Objects.requireNonNull(simpleName, "simpleName");
        Objects.requireNonNull(language, "language");
        Objects.requireNonNull(content, "content");
    }

    /**
     * The language of a generated source file.
     */
    public enum Language {
        JAVA("java"),
        KOTLIN("kt");

        private final String fileExtension;

        Language(final String fileExtension) {
            this.fileExtension = fileExtension;
        }

        public String fileExtension() {
            return fileExtension;
        }
    }
}
